<script setup lang="ts">
import {Play} from 'lucide-vue-next'
const route=useRoute(),{data}=useCatalog(),p=usePlayer()
const artist=computed(()=>data.value.artists.find(a=>a.slug===route.params.slug))
const albums=computed(()=>data.value.albums.filter(a=>a.artistId===artist.value?.id))
const tracks=computed(()=>data.value.tracks.filter(t=>t.artistId===artist.value?.id))
useSeoMeta({title:()=>artist.value?artist.value.name+' | WEBMUSIC':'Artista | WEBMUSIC',description:()=>artist.value?.description||'Conoce nuevos artistas en WEBMUSIC.',ogImage:()=>artist.value?.cover})
</script>
<template><NuxtLayout><div v-if="artist"><div class="mb-10 flex flex-col items-center gap-7 rounded-3xl bg-gradient-to-br from-violet-800/25 to-[#191b28] p-8 text-center md:flex-row md:text-left"><img :src="artist.cover" :alt="artist.name" class="h-44 w-44 rounded-full object-cover shadow-2xl"/><div><p class="mb-2 text-xs font-bold uppercase tracking-widest text-violet-400">Artista</p><h1 class="text-4xl font-extrabold">{{artist.name}}</h1><p class="mt-3 max-w-lg text-sm leading-6 text-[#c0bece]">{{artist.description}}</p><button v-if="tracks.length" class="mt-5 flex items-center gap-2 rounded-full bg-violet-500 px-6 py-3 text-sm font-bold" @click="p.start(tracks[0],tracks)"><Play :size="17" fill="currentColor"/> Reproducir</button></div></div><h2 class="mb-4 text-2xl font-bold">Canciones</h2><div class="mb-10 rounded-xl bg-[#151822] p-2"><TrackRow v-for="(track,i) in tracks" :key="track.id" :track="track" :index="i" :artist="artist" :album="albums.find(a=>a.id===track.albumId)" :queue="tracks"/></div><h2 class="mb-4 text-2xl font-bold">Discografía</h2><div class="grid grid-cols-2 gap-4 md:grid-cols-4"><AlbumCard v-for="album in albums" :key="album.id" :album="album" :artist="artist" :tracks="tracks"/></div></div><div v-else class="py-20 text-center"><h1 class="text-2xl font-bold">Artista no encontrado</h1><NuxtLink to="/artistas" class="mt-4 inline-block text-violet-400">Ver artistas</NuxtLink></div></NuxtLayout></template>
